def solve(data: dict) -> bool:
    total_sum = sum(data["nums"])
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    n = len(data["nums"])

    # Create a DP table to store whether it's possible to form target_sum using the first i elements
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]

    # Base case: it's always possible to form a sum of 0 using any subset
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            if data["nums"][i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - data["nums"][i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target_sum]

from typing import List

def solve(data: dict) -> bool:
    # Edge case: if the list is empty, return True
    if not data['nums']:
        return True

    # Calculate the total sum of the numbers
    total_sum = sum(data['nums'])

    # If the total sum is odd, it cannot be split into two equal subsets
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2

    # Check if there exists a subset of numbers that sums up to the target sum
    return can_partition(data['nums'], target_sum)

def can_partition(nums: List[int], target: int) -> bool:
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: there is always a subset that sums up to 0 (by choosing no elements)
    dp[0][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(target + 1):
            if j >= nums[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

# Test cases
test_cases = [
    {"nums": [], "expected_output": True},
    {"nums": [1, 5, 11, 5], "expected_output": True},
    {"nums": [1, 2, 3, 5], "expected_output": False},
    {"nums": [0, 0, 0], "expected_output": True}
]

for test_case in test_cases:
    result = solve(test_case)
    assert result == test_case["expected_output"], f"Failed on {test_case}: expected {test_case['expected_output']}, got {result}"
print("All tests passed!")
